    for i in range(n):
        school = schools[i]
        if i + 1 in chosen_ones:
            school_strengths[school][1] = max(school_strengths[school][1], powers[i])
        else:
            school_strengths[school][0] = max(school_strengths[school][0], powers[i])

    total_chosen = sum(1 for s in school_strengths.values() if s[1] > s[0])
    additional_schools = 0

    for school, (non_chosen, chosen) in school_strengths.items():
        if total_chosen == k:
            break
        if chosen > non_chosen and non_chosen > 0:
            total_chosen -= 1
            additional_schools += 1

    if total_chosen < k:
        additional_schools += k - total_chosen

    print(additional_schools)

