def min_schools_to_make_up(n, m, k, powers, schools, chosen_ones):
    school_students = defaultdict(list)
    for i, school in enumerate(schools):
        school_students[school].append((powers[i], i + 1))

    for school in school_students:
        school_students[school].sort(reverse=True)

    chosen_schools = set(schools[i-1] for i in chosen_ones)
    required_schools = set(range(1, m+1)) - chosen_schools

    if k <= len(chosen_schools):
        return 0

    students_to_add = k - len(chosen_schools)
    schools_made_up = 0

    while students_to_add > 0:
        max_students = 0
        best_school = None

        for school in required_schools:
            if school_students[school]:
                max_students = max(max_students, school_students[school][0][0])

        for school in required_schools:
            if school_students[school] and school_students[school][0][0] == max_students:
                best_school = school
                break

        if best_school is None:
            break

        schools_made_up += 1
        students_to_add -= len(school_students[best_school])
        required_schools.remove(best_school)

    return schools_made_up

