    for i in range(n):
        school_students[schools[i]].append((powers[i], i+1))

    for school in school_students:
        school_students[school].sort(reverse=True)

    chosen_schools = set()
    for chosen in chosen_ones:
        chosen_schools.add(schools[chosen-1])

    schools_needed = 0
    for school in range(1, m+1):
        if school not in chosen_schools:
            continue

        strongest = school_students[school][0]
        if strongest[1] in chosen_ones:
            continue

        for alt_school in range(m+1, m+k+1):
            if alt_school not in chosen_schools and alt_school not in school_students:
                schools_needed += 1
                chosen_schools.add(alt_school)
                break
